pub fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    debug_assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}